<?php
require __DIR__.'/includes/bootstrap.php';
require __DIR__.'/includes/auth.php';
$token=trim((string)($_GET['token']??''));$row=auth_find_token($token,'email_verification');$success=false;
if($row){$pdo=db();$pdo->beginTransaction();try{$locked=auth_find_token($token,'email_verification',true);if(!$locked)throw new RuntimeException('Invalid token');q('UPDATE users SET email_verified_at=NOW() WHERE id=?',[(int)$locked['user_id']]);auth_mark_token_used((int)$locked['id']);$pdo->commit();$success=true;}catch(Throwable $exception){if($pdo->inTransaction())$pdo->rollBack();error_log('[email-verification] '.$exception->getMessage());}}
?>
<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>تأكيد البريد | Anas Work OS</title><link rel="stylesheet" href="assets/style.css"></head><body class="auth-page"><main class="auth-shell narrow"><a class="auth-brand" href="login.php"><span class="brand-mark">AN</span><div><strong>Anas Work OS</strong><small>تأكيد البريد</small></div></a><section class="auth-card"><?php if($success):?><div class="auth-success"><strong>تم تأكيد البريد</strong><p>أصبح بريد الحساب موثقاً ويمكن استخدامه لاستعادة كلمة المرور.</p></div><a class="btn block" href="<?= current_user()?'account_settings.php':'login.php' ?>"><?= current_user()?'إعدادات الحساب':'تسجيل الدخول' ?></a><?php else:?><div class="alert error"><span>رابط التأكيد منتهي أو مستخدم مسبقاً.</span></div><a class="btn secondary block" href="<?= current_user()?'account_settings.php':'login.php' ?>">المتابعة</a><?php endif;?></section></main></body></html>
